function tripletStatsLoaderGUI()
% tripletStatsLoaderGUI
%
% Standalone post-processing GUI for MLstructureFinder triplet CSV exports.
%
% Loads the full triplet CSV file generated by "Export triplets", reconstructs
% the same raw feature-statistics array used by Feature statistics, and launches
% a controls GUI that produces:
%
%   1) PDF of l/(x - x0)
%   2) PDF of b/a
%   3) Joint PDF: l/(x - x0) vs b/a
%   4) Joint PDF: l/(x - x0) vs x
%
% This GUI does not read Tecplot flow fields and does not re-run structure
% detection. It only interrogates the exported triplet CSV.

%% ----- state -----
S = struct();
S.cases = {};
S.curCase = 1;

%% ----- loader GUI -----
f = figure('Name','Triplet Statistics Loader', ...
           'NumberTitle','off', ...
           'MenuBar','none', ...
           'ToolBar','none', ...
           'Resize','off', ...
           'Position',[120 120 620 360]);

uicontrol(f,'Style','pushbutton', ...
    'String','Load full triplet CSV...', ...
    'FontSize',10, ...
    'Position',[20 310 180 30], ...
    'Callback',@onLoadCSV);

uicontrol(f,'Style','pushbutton', ...
    'String','Remove selected', ...
    'FontSize',10, ...
    'Position',[220 310 130 30], ...
    'Callback',@onRemoveSelected);

uicontrol(f,'Style','pushbutton', ...
    'String','Clear all', ...
    'FontSize',10, ...
    'Position',[370 310 100 30], ...
    'Callback',@onClearAll);

uicontrol(f,'Style','pushbutton', ...
    'String','Launch statistics GUI', ...
    'FontSize',10, ...
    'FontWeight','bold', ...
    'Position',[20 260 180 34], ...
    'Callback',@onLaunchStats);

hList = uicontrol(f,'Style','listbox', ...
    'FontSize',10, ...
    'Position',[20 60 580 185], ...
    'String',{}, ...
    'Callback',@onSelectCase);

hInfo = uicontrol(f,'Style','text', ...
    'String','No triplet CSV loaded.', ...
    'FontSize',10, ...
    'HorizontalAlignment','left', ...
    'Position',[20 20 580 25]);

guidata(f,S);

%% ----- callbacks -----
    function onLoadCSV(~,~)
        S = guidata(f);

        [fn,fp] = uigetfile({'*.csv','CSV files (*.csv)';'*.*','All files'}, ...
                            'Select full triplet CSV', ...
                            'MultiSelect','on');

        if isequal(fn,0)
            return;
        end

        if ischar(fn)
            fn = {fn};
        end

        for k = 1:numel(fn)
            fullp = fullfile(fp,fn{k});

            try
                c = readTripletCSV_(fullp);
            catch ME
                warning('Failed to read %s: %s', fullp, ME.message);
                errordlg(sprintf('Failed to read:\n%s\n\n%s',fullp,ME.message), ...
                         'CSV read error');
                continue;
            end

            c.name = makeUniqueCaseName_(S.cases, c.name);
            S.cases{end+1} = c; %#ok<AGROW>

            fprintf('Loaded %s: %d triplets\n', c.name, numel(c.zoneIdx));
        end

        if ~isempty(S.cases)
            S.curCase = numel(S.cases);
        else
            S.curCase = 1;
        end

        guidata(f,S);
        refreshLoaderList();
    end

    function onRemoveSelected(~,~)
        S = guidata(f);

        if isempty(S.cases)
            return;
        end

        idx = get(hList,'Value');
        idx = max(1,min(numel(S.cases),idx));

        S.cases(idx) = [];

        if isempty(S.cases)
            S.curCase = 1;
        else
            S.curCase = max(1,min(numel(S.cases),idx));
        end

        guidata(f,S);
        refreshLoaderList();
    end

    function onClearAll(~,~)
        S = guidata(f);
        S.cases = {};
        S.curCase = 1;
        guidata(f,S);
        refreshLoaderList();
    end

    function onSelectCase(~,~)
        S = guidata(f);

        if isempty(S.cases)
            return;
        end

        S.curCase = get(hList,'Value');
        S.curCase = max(1,min(numel(S.cases),S.curCase));

        guidata(f,S);
        refreshLoaderList();
    end

    function onLaunchStats(~,~)
        S = guidata(f);

        if isempty(S.cases)
            errordlg('Load at least one full triplet CSV first.', ...
                     'Triplet statistics');
            return;
        end

        idx = get(hList,'Value');
        idx = max(1,min(numel(S.cases),idx));

        tripletStatsGUI_(S.cases{idx});
    end

    function refreshLoaderList()
        S = guidata(f);

        if isempty(S.cases)
            set(hList,'String',{},'Value',1);
            set(hInfo,'String','No triplet CSV loaded.');
            return;
        end

        names = cell(numel(S.cases),1);

        for ii = 1:numel(S.cases)
            c = S.cases{ii};
            nAll = numel(c.zoneIdx);
            nLab = sum(c.labelled == 1);
            nAcc = sum(c.accepted == 1);
            nRej = sum(c.accepted == 0);

            names{ii} = sprintf('%s    [%d triplets, %d labelled, %d accepted, %d rejected]', ...
                                c.name,nAll,nLab,nAcc,nRej);
        end

        S.curCase = max(1,min(numel(S.cases),S.curCase));

        set(hList,'String',names,'Value',S.curCase);

        c = S.cases{S.curCase};

        set(hInfo,'String',sprintf('Selected: %s | file: %s', ...
            c.name,c.filename));
    end
end

function c = readTripletCSV_(filename)
% Read a full triplet CSV export and reconstruct feature-stats quantities.
%
% Robust version:
%   - finds the actual CSV header line explicitly
%   - handles files with blank/comment/metadata lines before the header
%   - then reads the table from that header line onward

headerLine = findTripletHeaderLine_(filename);

opts = detectImportOptions(filename, ...
    'FileType','text', ...
    'Delimiter',',', ...
    'VariableNamingRule','preserve', ...
    'NumHeaderLines',headerLine-1);

T = readtable(filename,opts);

varNames = T.Properties.VariableNames;

% Debug print: useful if MATLAB still misreads the file.
fprintf('\nRead CSV header from line %d:\n', headerLine);
for ii = 1:numel(varNames)
    fprintf('  %2d: %s\n', ii, varNames{ii});
end

idxZone = findColumn_(varNames, {'zone'});
idxXL   = findColumn_(varNames, {'x_upstream','xupstream'});
idxYL   = findColumn_(varNames, {'y_upstream','yupstream'}, false);
idxXC   = findColumn_(varNames, {'x_core','xcore'});
idxYC   = findColumn_(varNames, {'y_core','ycore'}, false);
idxXR   = findColumn_(varNames, {'x_downstream','xdownstream'});
idxYR   = findColumn_(varNames, {'y_downstream','ydownstream'}, false);
idxL    = findColumn_(varNames, {'l'});
idxLab  = findColumn_(varNames, {'labelled','labeled'}, false);
idxAcc  = findColumn_(varNames, {'accepted','accept'}, false);

zoneIdx = tableColNumeric_(T, idxZone);
xL      = tableColNumeric_(T, idxXL);
xc      = tableColNumeric_(T, idxXC);
xR      = tableColNumeric_(T, idxXR);

if isempty(idxYL)
    yL = NaN(size(xL));
else
    yL = tableColNumeric_(T, idxYL);
end

if isempty(idxYC)
    yc = NaN(size(xL));
else
    yc = tableColNumeric_(T, idxYC);
end

if isempty(idxYR)
    yR = NaN(size(xL));
else
    yR = tableColNumeric_(T, idxYR);
end

lCSV = tableColNumeric_(T, idxL);

% Prefer geometric l from xR - xL, but retain CSV consistency if needed.
lGeom = xR - xL;
l = lGeom;

badL = ~isfinite(l) | l <= 0;
l(badL & isfinite(lCSV)) = lCSV(badL & isfinite(lCSV));

xref    = 0.5*(xL + xR);
l_minus = xc - xL;
l_plus  = xR - xc;

if isempty(idxLab)
    labelled = zeros(size(zoneIdx));
else
    labelled = tableColNumeric_(T, idxLab);
    labelled(~isfinite(labelled)) = 0;
end

if isempty(idxAcc)
    accepted = 2*ones(size(zoneIdx));
else
    accepted = tableColNumeric_(T, idxAcc);
    accepted(~isfinite(accepted)) = 2;
end

% Sanitise accepted convention.
% 1 = accepted, 0 = rejected, 2 = unlabelled.
accepted(~ismember(accepted,[0 1 2])) = 2;

% If labelled column exists but accepted says 2, honour accepted=2 as unlabelled.
labelled = double(labelled ~= 0);
labelled(accepted == 2) = 0;

raw = [zoneIdx, xL, xc, xR, l, xref, l_minus, l_plus];

[~,base,~] = fileparts(filename);

c = struct();
c.name      = base;
c.filename  = filename;
c.table     = T;
c.raw       = raw;

c.zoneIdx   = zoneIdx;
c.xL        = xL;
c.yL        = yL;
c.xc        = xc;
c.yc        = yc;
c.xR        = xR;
c.yR        = yR;
c.l         = l;
c.xref      = xref;
c.l_minus   = l_minus;
c.l_plus    = l_plus;
c.labelled  = labelled;
c.accepted  = accepted;
end

function headerLine = findTripletHeaderLine_(filename)
% Find the real triplet CSV header line.
%
% Expected header contains at least:
%   zone, x_upstream, x_core, x_downstream

fid = fopen(filename,'r');

if fid < 0
    error('Could not open file: %s', filename);
end

cleaner = onCleanup(@()fclose(fid));

headerLine = [];
lineNo = 0;

while true
    ln = fgetl(fid);

    if ~ischar(ln)
        break;
    end

    lineNo = lineNo + 1;

    % Remove UTF-8 BOM if present.
    if lineNo == 1 && ~isempty(ln)
        ln = regexprep(ln,'^\xEF\xBB\xBF','');
    end

    normLn = lower(ln);
    normLn = regexprep(normLn,'[^a-z0-9_,]','');

    hasZone = contains(normLn,'zone');
    hasXL   = contains(normLn,'x_upstream') || contains(normLn,'xupstream');
    hasXC   = contains(normLn,'x_core')     || contains(normLn,'xcore');
    hasXR   = contains(normLn,'x_downstream') || contains(normLn,'xdownstream');

    if hasZone && hasXL && hasXC && hasXR
        headerLine = lineNo;
        return;
    end
end

error('Could not find triplet CSV header line containing zone, x_upstream, x_core and x_downstream.');
end

