acceptedAll = caseData.accepted(:);

% Defaults match the original featureStatsGUI style.
x0_default       = 0;
xMin_default     = 0;
xMax_default     = inf;
lxMin_default    = 0;
lxMax_default    = inf;
ratioMin_default = 0.125;
ratioMax_default = 8;

fsTick_default  = 10;
fsLabel_default = 12;
