          'Position',[0.25 0.20 0.70 0.55], ...
          'HorizontalAlignment','left');

refreshPlots();

    function v = getVal(h, defaultVal)
        str = strtrim(get(h,'String'));

        if isempty(str)
            v = defaultVal;
            set(h,'String',num2str(defaultVal));
            return;
        end

        if strcmpi(str,'inf') || strcmpi(str,'+inf')
            v = inf;
            return;
        end

        v = str2double(str);

        if ~isfinite(v)
            v = defaultVal;

            if isinf(defaultVal)
                set(h,'String','inf');
            else
                set(h,'String',num2str(defaultVal));
            end
        end
    end

    function refreshPlots()
        cfg.filters.x0       = getVal(hX0,   x0_default);
        cfg.filters.xMin     = getVal(hXMin, xMin_default);
        cfg.filters.xMax     = getVal(hXMax, xMax_default);
        cfg.filters.lxMin    = getVal(hLxMin,lxMin_default);
        cfg.filters.lxMax    = getVal(hLxMax,lxMax_default);
        cfg.filters.ratioMin = getVal(hRMin, ratioMin_default);
        cfg.filters.ratioMax = getVal(hRMax, ratioMax_default);

        set(hX0,  'String',num2str(cfg.filters.x0));
        set(hXMin,'String',num2str(cfg.filters.xMin));

        if isfinite(cfg.filters.xMax)
            set(hXMax,'String',num2str(cfg.filters.xMax));
        else
            set(hXMax,'String','inf');
        end

        if isfinite(cfg.filters.lxMax)
            set(hLxMax,'String',num2str(cfg.filters.lxMax));
        else
            set(hLxMax,'String','inf');
        end

        cfg.style.fsTick  = max(1, round(getVal(hFsTick,  fsTick_default)));
        cfg.style.fsLabel = max(1, round(getVal(hFsLabel, fsLabel_default)));
        cfg.style.fsTitle = max(1, round(getVal(hFsTitle, fsTitle_default)));

        set(hFsTick, 'String', num2str(cfg.style.fsTick));
        set(hFsLabel,'String', num2str(cfg.style.fsLabel));
        set(hFsTitle,'String', num2str(cfg.style.fsTitle));

        cfg.lx.nbins     = max(5, round(getVal(hNbinsLx,       nbinsLx_default)));
        cfg.ratio.nbins  = max(5, round(getVal(hNbinsRatio,    nbinsRatio_default)));
        cfg.joint.nbinsL = max(5, round(getVal(hNbinsJointL,   nbinsJointLx_default)));
        cfg.joint.nbinsR = max(5, round(getVal(hNbinsJointR,   nbinsJointR_default)));
        cfg.lx_x.nbinsX  = max(5, round(getVal(hNbinsLxX_X,    nbinsLxX_X_default)));
        cfg.lx_x.nbinsL  = max(5, round(getVal(hNbinsLxX_L,    nbinsLxX_L_default)));

        cfg.lx_x.xPlotMin = getVal(hXPlotMin, xPlotMin_default);

        strXMax = strtrim(get(hXPlotMax,'String'));
        if isempty(strXMax)
            cfg.lx_x.xPlotMax = NaN;
        elseif strcmpi(strXMax,'inf') || strcmpi(strXMax,'+inf')
            cfg.lx_x.xPlotMax = inf;
            set(hXPlotMax,'String','inf');
        else
            tmp = str2double(strXMax);
            if ~isfinite(tmp)
                cfg.lx_x.xPlotMax = NaN;
                set(hXPlotMax,'String','');
            else
                cfg.lx_x.xPlotMax = tmp;
            end
        end

        set(hNbinsLx,     'String',num2str(cfg.lx.nbins));
        set(hNbinsRatio,  'String',num2str(cfg.ratio.nbins));
        set(hNbinsJointL, 'String',num2str(cfg.joint.nbinsL));
        set(hNbinsJointR, 'String',num2str(cfg.joint.nbinsR));
        set(hNbinsLxX_X,  'String',num2str(cfg.lx_x.nbinsX));
        set(hNbinsLxX_L,  'String',num2str(cfg.lx_x.nbinsL));

        denom = xref - cfg.filters.x0;
        lnorm = l ./ denom;
        ratio = l_plus ./ l_minus;

        mask = isfinite(lnorm) & isfinite(ratio) & isfinite(xref) & ...
               isfinite(l) & isfinite(l_minus) & isfinite(l_plus);

        if isfinite(cfg.filters.xMin)
            mask = mask & (xref >= cfg.filters.xMin);
        end

        if isfinite(cfg.filters.xMax)
            mask = mask & (xref <= cfg.filters.xMax);
        end

        if isfinite(cfg.filters.lxMin)
            mask = mask & (lnorm >= cfg.filters.lxMin);
        end

        if isfinite(cfg.filters.lxMax)
            mask = mask & (lnorm <= cfg.filters.lxMax);
        end

        if isfinite(cfg.filters.ratioMin)
            mask = mask & (ratio >= cfg.filters.ratioMin);
        end

        if isfinite(cfg.filters.ratioMax)
            mask = mask & (ratio <= cfg.filters.ratioMax);
        end

        subsetVal = get(hSubset,'Value');

        switch subsetVal
            case 1  % all
                subsetName = 'all triplets';

            case 2  % accepted only
                mask = mask & (acceptedAll == 1);
                subsetName = 'accepted only';

            case 3  % rejected only
                mask = mask & (acceptedAll == 0);
                subsetName = 'rejected only';

            case 4  % labelled only
                mask = mask & (labelledAll == 1);
                subsetName = 'labelled only';

            case 5  % unlabelled only
                mask = mask & (acceptedAll == 2);
                subsetName = 'unlabelled only';

            otherwise
                subsetName = 'all triplets';
        end

        lnormF = lnorm(mask);
        ratioF = ratio(mask);
        xrefF  = xref(mask);
        zoneF  = zoneIdxAll(mask);

        fprintf('\nTriplet statistics for case: %s\n', caseData.name);
        fprintf('Subset: %s\n', subsetName);
        fprintf('Feature stats: %d / %d triplets pass current thresholds.\n', ...
                numel(lnormF), numel(lnorm));

        printScalarStats_('l/(x - x0)', lnormF, zoneF);
        printScalarStats_('b/a', ratioF, zoneF);

        plotLnormPDF();
        plotRatioPDF();
        plotJointLnormRatio();
        plotJointLnormX();

        function plotLnormPDF()
            if isempty(figLx) || ~isvalid(figLx)
                figLx = figure('Name',['PDF of l/(x - x_0) — ' caseData.name], ...
                               'NumberTitle','off');
            end

            figure(figLx);
            clf(figLx);
            ax = axes('Parent',figLx);

            if ~isempty(lnormF)
                histogram(ax, lnormF, cfg.lx.nbins, 'Normalization','pdf');
                xlabel(ax,'l / (x - x_0)');
                ylabel(ax,'PDF');
                title(ax,sprintf('PDF of l / (x - x_0) — %s',subsetName), ...
                      'Interpreter','none');

                if isfinite(cfg.filters.lxMin) && isfinite(cfg.filters.lxMax)
                    xlim(ax,[cfg.filters.lxMin cfg.filters.lxMax]);
                end

                grid(ax,'on');
                box(ax,'on');
                applyStyle_(ax, cfg.style);
            else
                noSamples_(ax);
            end
        end

        function plotRatioPDF()
            if isempty(figRatio) || ~isvalid(figRatio)
                figRatio = figure('Name',['PDF of b/a — ' caseData.name], ...
                                  'NumberTitle','off');
            end

            figure(figRatio);
            clf(figRatio);
            ax = axes('Parent',figRatio);

            if ~isempty(ratioF)
                histogram(ax, ratioF, cfg.ratio.nbins, 'Normalization','pdf');
                xlabel(ax,'b/a');
                ylabel(ax,'PDF');
                title(ax,sprintf('PDF of b/a — %s',subsetName), ...
                      'Interpreter','none');

                if isfinite(cfg.filters.ratioMin) && isfinite(cfg.filters.ratioMax)
                    xlim(ax,[cfg.filters.ratioMin cfg.filters.ratioMax]);
                end

                grid(ax,'on');
                box(ax,'on');
                applyStyle_(ax, cfg.style);
            else
                noSamples_(ax);
            end
        end

        function plotJointLnormRatio()
            if isempty(figJoint) || ~isvalid(figJoint)
                figJoint = figure('Name',['Joint PDF: l/(x-x_0) vs b/a — ' caseData.name], ...
                                  'NumberTitle','off');
            end

            figure(figJoint);
            clf(figJoint);
            ax = axes('Parent',figJoint);

            if ~isempty(lnormF) && ~isempty(ratioF)
                [N2, edgesL2, edgesR2] = histcounts2(lnormF, ratioF, ...
                                                    [cfg.joint.nbinsL cfg.joint.nbinsR]);

                if any(N2(:))
                    centersL = 0.5*(edgesL2(1:end-1) + edgesL2(2:end));
                    centersR = 0.5*(edgesR2(1:end-1) + edgesR2(2:end));

                    [XL, YR] = meshgrid(centersL, centersR);

                    P2 = N2';
                    P2 = P2 / sum(P2(:));

                    surf(ax, XL, YR, P2);
                    shading(ax,'interp');

                    xlabel(ax,'l / (x - x_0)');
                    ylabel(ax,'b/a');
                    zlabel(ax,'Probability');
                    title(ax,sprintf('Joint PDF: l/(x-x_0) vs b/a — %s',subsetName), ...
                          'Interpreter','none');

                    view(ax,35,30);
                    grid(ax,'on');
                    box(ax,'on');
                    applyStyle_(ax, cfg.style);
                else
                    noSamples_(ax);
                end
            else
                noSamples_(ax);
            end
        end

        function plotJointLnormX()
            if isempty(figLxX) || ~isvalid(figLxX)
                figLxX = figure('Name',['Joint PDF: l/(x-x_0) vs x — ' caseData.name], ...
                                'NumberTitle','off');
            end

            figure(figLxX);
            clf(figLxX);
            ax = axes('Parent',figLxX);

            if ~isempty(lnormF) && ~isempty(xrefF)
                xUse = xrefF;
                lUse = lnormF;

                if isfinite(cfg.lx_x.xPlotMin)
                    idx = xUse >= cfg.lx_x.xPlotMin;
                    xUse = xUse(idx);
                    lUse = lUse(idx);
                end

                if isfinite(cfg.lx_x.xPlotMax)
                    idx = xUse <= cfg.lx_x.xPlotMax;
                    xUse = xUse(idx);
                    lUse = lUse(idx);
                end

                if numel(xUse) > 0
                    [N2, edgesX, edgesL] = histcounts2(xUse, lUse, ...
                                                       [cfg.lx_x.nbinsX cfg.lx_x.nbinsL]);

                    if any(N2(:))
                        centersX = 0.5*(edgesX(1:end-1) + edgesX(2:end));
                        centersL = 0.5*(edgesL(1:end-1) + edgesL(2:end));

                        [XX, LL] = meshgrid(centersX, centersL);

                        P2 = N2';
                        P2 = P2 / sum(P2(:));

                        surf(ax, XX, LL, P2);
                        shading(ax,'interp');

                        xlabel(ax,'x');
                        ylabel(ax,'l / (x - x_0)');
                        zlabel(ax,'Probability');
                        title(ax,sprintf('Joint PDF: l/(x-x_0) vs x — %s',subsetName), ...
                              'Interpreter','none');

                        view(ax,35,30);
                        grid(ax,'on');
                        box(ax,'on');
                        applyStyle_(ax, cfg.style);
                    else
                        noSamples_(ax);
                    end
                else
                    text(ax,0.5,0.5,'No samples in x-range', ...
                         'HorizontalAlignment','center', ...
                         'VerticalAlignment','middle');
                    axis(ax,'off');
                end
            else
                noSamples_(ax);
            end
        end
    end

    function bringPlotsForward()
        figs = [figLx figRatio figJoint figLxX];

        for kk = 1:numel(figs)
            if ~isempty(figs(kk)) && isvalid(figs(kk))
                figure(figs(kk));
            end
        end

        figure(fStats);
    end
end


function printScalarStats_(name, vals, zoneF)
if isempty(vals)
    fprintf('  %s: no samples after thresholds.\n', name);
    return;
end

mu  = mean(vals,'omitnan');
sig = std(vals,'omitnan');

[N, edges] = histcounts(vals, 30);

if any(N)
    [~, iMax] = max(N);
    mpv = 0.5*(edges(iMax) + edges(iMax+1));
else
    mpv = NaN;
end

fprintf('  %s: mean = %.4g, std = %.4g, most probable ≈ %.4g\n', ...
        name, mu, sig, mpv);

[maxVal, idxMax] = max(vals);

if ~isempty(zoneF) && numel(zoneF) >= idxMax
    fprintf('  Max %s = %.4g in zone %d\n', ...
            name, maxVal, zoneF(idxMax));
else
    fprintf('  Max %s = %.4g\n', name, maxVal);
end
end


function applyStyle_(ax, style)
if ~ishandle(ax)
    return;
end

set(ax,'FontSize',style.fsTick);

xl = get(ax,'XLabel');
yl = get(ax,'YLabel');
zl = get(ax,'ZLabel');
tl = get(ax,'Title');

if ~isempty(xl)
    set(xl,'FontSize',style.fsLabel);
end

if ~isempty(yl)
    set(yl,'FontSize',style.fsLabel);
end

if ~isempty(zl)
    set(zl,'FontSize',style.fsLabel);
end

if ~isempty(tl)
    set(tl,'FontSize',style.fsTitle);
end
end


function noSamples_(ax)
text(ax,0.5,0.5,'No samples', ...
     'HorizontalAlignment','center', ...
     'VerticalAlignment','middle');
axis(ax,'off');
end


function idx = findColumn_(varNames, patterns, required)
if nargin < 3
    required = true;
end

idx = [];

normNames = cellfun(@normaliseName_, varNames, 'UniformOutput', false);
normPat   = cellfun(@normaliseName_, patterns, 'UniformOutput', false);

% First pass: exact normalised match.
for p = 1:numel(normPat)
    hit = find(strcmp(normNames,normPat{p}),1,'first');

    if ~isempty(hit)
        idx = hit;
        return;
    end
end

% Second pass: contains normalised pattern.
for p = 1:numel(normPat)
    hit = find(contains(normNames,normPat{p}),1,'first');

    if ~isempty(hit)
        idx = hit;
        return;
    end
end

% Special handling for accepted column with verbose header.
if any(strcmp(normPat,'accepted')) || any(strcmp(normPat,'accept'))
    hit = find(contains(normNames,'accepted') | contains(normNames,'accept'),1,'first');

    if ~isempty(hit)
        idx = hit;
        return;
    end
end

if required
    error('Could not find required CSV column matching: %s', strjoin(patterns,', '));
end
end


function s = normaliseName_(s)
s = lower(char(s));
s = regexprep(s,'[^a-z0-9]','');
end


function v = tableColNumeric_(T, idx)
name = T.Properties.VariableNames{idx};
x = T.(name);

if isnumeric(x)
    v = double(x);
elseif islogical(x)
    v = double(x);
elseif iscell(x)
    v = str2double(string(x));
elseif isstring(x)
    v = str2double(x);
elseif ischar(x)
    v = str2double(string(x));
else
    try
        v = double(x);
    catch
        v = str2double(string(x));
    end
end

v = v(:);
end


function nameOut = makeUniqueCaseName_(cases, nameIn)
nameOut = nameIn;

if isempty(cases)
    return;
end

existing = cellfun(@(c)c.name, cases, 'UniformOutput', false);

if ~any(strcmp(existing,nameOut))
    return;
end

base = nameIn;
k = 2;

while true
    cand = sprintf('%s_%d',base,k);

    if ~any(strcmp(existing,cand))
        nameOut = cand;
        return;
    end

    k = k + 1;
end
end